{"code": "import pathlib
import os

data_dir = pathlib.Path('data/web_scraped_small')
# Check all files in the directory and their extensions
all_files = []
for root, dirs, files in os.walk(data_dir):
    for file in files:
        file_path = os.path.join(root, file)
        ext = os.path.splitext(file)[1].lower()
        all_files.append((file_path, ext))

print(f"Total files found: {len(all_files)}")
for fp, ext in sorted(all_files):
    print(f"{fp} - Extension: {ext}")"}

