{"code": "import PIL.Image
from pathlib import Path

data_dir = Path('data/web_scraped_small')
all_jpgs = list(data_dir.glob('*/*.jpg'))

print("Checking each file with PIL...")
problem_files = []
for f in all_jpgs:
    try:
        img = PIL.Image.open(f)
        img.verify()  # Verify it's a valid image
        # Reopen after verify (verify closes the file)
        img = PIL.Image.open(f)
        print(f"  OK: {f.name}")
    except Exception as e:
        print(f"  ERROR: {f.name} - {e}")
        problem_files.append((f.name, str(e)))

if problem_files:
    print(f"\nFound {len(problem_files)} problematic files:")
    for name, err in problem_files:
        print(f"  {name}: {err}")
else:
    print("\nAll files can be opened with PIL.Image.open")"}

